#include "gpi/adaptive_experimentation.hpp"

#include "gpi/filesystem_safety.hpp"
#include "gpi/foreign_project_intelligence.hpp"
#include "gpi/process_runner.hpp"

#include <algorithm>
#include <chrono>
#include <cctype>
#include <fstream>
#include <sstream>
#include <stdexcept>

namespace genomic::gpi { namespace {
std::string read(const std::filesystem::path& path){std::ifstream in(path,std::ios::binary);if(!in)throw std::runtime_error("Cannot read "+path.string());return {std::istreambuf_iterator<char>(in),{}};}
void write(const std::filesystem::path& path,const std::string& text){std::filesystem::create_directories(path.parent_path());std::ofstream out(path,std::ios::binary|std::ios::trunc);if(!out)throw std::runtime_error("Cannot write "+path.string());out<<text;}
bool source(const std::filesystem::path& path){const auto ext=path.extension().string();return ext==".cpp"||ext==".cc"||ext==".cxx";}
void copyTree(const std::filesystem::path& from,const std::filesystem::path& to){std::error_code ec;std::filesystem::create_directories(to);for(const auto& item:std::filesystem::recursive_directory_iterator(from,std::filesystem::directory_options::skip_permission_denied)){if(item.is_symlink())throw std::runtime_error("Symlink in isolated source import");const auto destination=to/std::filesystem::relative(item.path(),from);if(item.is_directory())std::filesystem::create_directories(destination);else if(item.is_regular_file()){std::filesystem::create_directories(destination.parent_path());std::filesystem::copy_file(item.path(),destination,std::filesystem::copy_options::overwrite_existing,ec);if(ec)throw std::runtime_error("Cannot copy isolated source import");}}}
std::filesystem::path findExecutable(const NativeBuildResult& result,const BuildContract& contract){for(const auto& artifact:result.artifacts)if(artifact.extension()==".exe"&&std::find(contract.executables.begin(),contract.executables.end(),artifact.stem().string())!=contract.executables.end())return artifact;return {};}
bool accepted(const std::string& output,const AdaptiveBehaviourOracle& oracle,int exit){return exit==oracle.expectedExitCode&&output.find(oracle.requiredOutput)!=std::string::npos&&(oracle.forbiddenOutput.empty()||output.find(oracle.forbiddenOutput)==std::string::npos);}
struct Literal {std::size_t begin{}, end{};std::string value;};
std::vector<Literal> literals(const std::string& text){std::vector<Literal> result;for(std::size_t i=0;i<text.size();++i){if(text[i]!='"')continue;const auto begin=i++;std::string value;bool closed=false;for(;i<text.size();++i){if(text[i]=='\\'&&i+1<text.size()){const auto escaped=text[++i];value+=escaped=='n'?'\n':escaped=='r'?'\r':escaped=='t'?'\t':escaped;continue;}if(text[i]=='"'){closed=true;break;}value+=text[i];}if(closed)result.push_back({begin,i+1,value});}return result;}
std::string quote(std::string value){std::string result="\"";for(const char c:value){if(c=='\\'||c=='\"')result+='\\';result+=c;}return result+'\"';}
bool observedLiteral(const std::string& output,std::string literal){if(output.find(literal)!=std::string::npos)return true;while(!literal.empty()&&(literal.back()=='\n'||literal.back()=='\r'||literal.back()==' '||literal.back()=='\t'))literal.pop_back();return !literal.empty()&&output.find(literal)!=std::string::npos;}
bool knownExperience(const std::filesystem::path& path){if(path.empty()||!std::filesystem::exists(path))return false;const auto text=read(path);return text.find("GDIAD1|success|observable_literal_substitution")!=std::string::npos||text.find("GDIAM1|principle|observable_literal_substitution")!=std::string::npos;}
bool failedBefore(const std::filesystem::path& path,const std::string& detail){return !path.empty()&&std::filesystem::exists(path)&&read(path).find("GDIAD1|failed|observable_literal_substitution|"+detail)!=std::string::npos;}
void remember(const std::filesystem::path& path,const std::string& status,const std::string& detail){if(path.empty())return;std::filesystem::create_directories(path.parent_path());std::ofstream out(path,std::ios::binary|std::ios::app);if(!out)throw std::runtime_error("Cannot persist adaptive experience");out<<"GDIAD1|"<<status<<"|observable_literal_substitution|"<<detail<<'\n';}
void writeReport(const AdaptiveExperimentConfig& cfg,AdaptiveExperimentResult& result){result.reportPath=cfg.isolatedWorkspace/"adaptive_experiment.json";std::ofstream out(result.reportPath);out<<"{\n  \"format\": \"GDIAD1\",\n  \"outcome\": \""<<toString(result.outcome)<<"\",\n  \"attempts\": "<<result.attempts.size()<<",\n  \"suppressed_failed_hypotheses\": "<<result.suppressedFailedHypotheses<<",\n  \"experience_used\": "<<(result.experienceUsed?"true":"false")<<",\n  \"experience_persisted\": "<<(result.experiencePersisted?"true":"false")<<",\n  \"original_untouched\": "<<(result.originalUntouched?"true":"false")<<",\n  \"reason\": \""<<result.reason<<"\"\n}\n";}
}
const char* toString(const AdaptiveExperimentOutcome value) noexcept {switch(value){case AdaptiveExperimentOutcome::Complete:return "COMPLETE";case AdaptiveExperimentOutcome::AlreadySatisfied:return "ALREADY_SATISFIED";case AdaptiveExperimentOutcome::Blocked:return "BLOCKED";case AdaptiveExperimentOutcome::Failed:return "FAILED";}return "FAILED";}
AdaptiveTrainingResult trainAdaptiveExperienceModel(const AdaptiveTrainingConfig& cfg){
    if(cfg.protectedProjects.empty()||cfg.modelPath.empty())throw std::invalid_argument("Adaptive training requires protected projects and a model path");
    AdaptiveTrainingResult result;if(!cfg.modelPath.parent_path().empty())std::filesystem::create_directories(cfg.modelPath.parent_path());std::ofstream model(cfg.modelPath,std::ios::binary|std::ios::app);if(!model)throw std::runtime_error("Cannot open adaptive experience model");
    for(const auto& input:cfg.protectedProjects){try{const auto project=std::filesystem::absolute(input);if(!std::filesystem::is_directory(project))throw std::runtime_error("not a directory");const auto hash=computeDirectoryTreeHash(project);const auto contract=discoverBuildContract(project);std::size_t literalsSeen=0;for(const auto& item:std::filesystem::recursive_directory_iterator(project)){if(!item.is_regular_file()||!source(item.path()))continue;literalsSeen+=literals(read(item.path())).size();}if(cfg.verifyBaselines){NativeBuildConfig build=cfg.nativeBuild;build.originalProject=project;build.isolatedWorkspace=cfg.modelPath.parent_path()/("training_"+std::to_string(result.projectsAnalysed));const auto baseline=executeNativeBuild(contract,build);if(baseline.baselineStatus!=BuildBaselineStatus::BaselineReproduced)throw std::runtime_error("baseline not reproduced");}model<<"GDIAM1|project|"<<hash<<'|'<<toString(contract.buildSystem)<<'|'<<literalsSeen<<'\n';if(literalsSeen>0){model<<"GDIAM1|principle|observable_literal_substitution|source_literal_to_runtime_oracle|verified_structural_context\n";result.observableLiteralContexts+=literalsSeen;}++result.projectsAnalysed;}catch(const std::exception& error){result.rejectedProjects.push_back(input.string()+": "+error.what());}}
    model.flush();result.modelPersisted=static_cast<bool>(model);return result;
}
AdaptiveExperimentResult runAdaptiveExperimentation(const AdaptiveExperimentConfig& cfg){
    if(cfg.protectedProject.empty()||cfg.isolatedWorkspace.empty()||cfg.oracle.requiredOutput.empty()||cfg.maxAttempts==0||cfg.maxAttempts>50)throw std::invalid_argument("Adaptive experimentation requires protected project, workspace, oracle, and 1..50 attempts");
    AdaptiveExperimentResult result;const auto original=std::filesystem::absolute(cfg.protectedProject);const auto workspace=std::filesystem::absolute(cfg.isolatedWorkspace);const auto before=computeDirectoryTreeHash(original);
    try {validateIsolatedWorkspace(original,workspace);const auto contract=discoverBuildContract(original);NativeBuildConfig baseline=cfg.nativeBuild;baseline.originalProject=original;baseline.isolatedWorkspace=workspace/"baseline";result.baseline=executeNativeBuild(contract,baseline);if(result.baseline.baselineStatus!=BuildBaselineStatus::BaselineReproduced){result.outcome=AdaptiveExperimentOutcome::Blocked;result.reason="baseline_not_reproduced";throw std::runtime_error("finalize");}
        const auto exe=findExecutable(result.baseline,contract);if(exe.empty()){result.outcome=AdaptiveExperimentOutcome::Blocked;result.reason="target_executable_not_discovered";throw std::runtime_error("finalize");}const auto run=workspace/"baseline_oracle";std::filesystem::create_directories(run);const auto stdoutPath=run/"stdout.log",stderrPath=run/"stderr.log";std::vector<std::string> command{exe.string()};command.insert(command.end(),cfg.oracle.arguments.begin(),cfg.oracle.arguments.end());const auto baselineRun=runProcess(command,run,{},stdoutPath,stderrPath,std::chrono::seconds(30));const auto observed=std::filesystem::exists(stdoutPath)?read(stdoutPath):"";if(baselineRun.launched&&!baselineRun.timedOut&&accepted(observed,cfg.oracle,baselineRun.exitCode)){result.outcome=AdaptiveExperimentOutcome::AlreadySatisfied;result.reason="runtime_oracle_already_satisfied";throw std::runtime_error("finalize");}if(!cfg.execute){result.outcome=AdaptiveExperimentOutcome::Blocked;result.reason="execution_not_authorized";throw std::runtime_error("finalize");}
        result.experienceUsed=knownExperience(cfg.experienceStore);std::size_t number=0;for(const auto& item:std::filesystem::recursive_directory_iterator(original)){if(!item.is_regular_file()||!source(item.path()))continue;const auto originalText=read(item.path());for(const auto& literal:literals(originalText)){if(literal.value.empty()||literal.value==cfg.oracle.requiredOutput||!observedLiteral(observed,literal.value))continue;const auto detail=literal.value+"->"+cfg.oracle.requiredOutput;if(failedBefore(cfg.experienceStore,detail)){++result.suppressedFailedHypotheses;continue;}if(++number>cfg.maxAttempts)break;const auto candidateRoot=workspace/("candidate_"+std::to_string(number));copyTree(original,candidateRoot);const auto relative=std::filesystem::relative(item.path(),original);const auto candidateFile=candidateRoot/relative;auto changed=originalText;changed.replace(literal.begin,literal.end-literal.begin,quote(cfg.oracle.requiredOutput));write(candidateFile,changed);AdaptiveHypothesisEvidence evidence;evidence.source=relative;evidence.before=literal.value;evidence.after=cfg.oracle.requiredOutput;evidence.rationale="Observed runtime output contained a unique source literal; substitute oracle-required output and verify natively";const auto candidateContract=discoverBuildContract(candidateRoot);NativeBuildConfig build=cfg.nativeBuild;build.originalProject=candidateRoot;build.isolatedWorkspace=workspace/("candidate_build_"+std::to_string(number));const auto candidateBuild=executeNativeBuild(candidateContract,build);evidence.compiled=candidateBuild.built;evidence.testsPassed=candidateBuild.testsPassed;const auto candidateExe=findExecutable(candidateBuild,candidateContract);if(candidateBuild.baselineStatus==BuildBaselineStatus::BaselineReproduced&&!candidateExe.empty()){const auto log=workspace/("candidate_run_"+std::to_string(number));std::filesystem::create_directories(log);const auto out=log/"stdout.log",err=log/"stderr.log";std::vector<std::string> candidateCommand{candidateExe.string()};candidateCommand.insert(candidateCommand.end(),cfg.oracle.arguments.begin(),cfg.oracle.arguments.end());const auto process=runProcess(candidateCommand,log,{},out,err,std::chrono::seconds(30));const auto text=std::filesystem::exists(out)?read(out):"";evidence.accepted=process.launched&&!process.timedOut&&accepted(text,cfg.oracle,process.exitCode);}result.attempts.push_back(evidence);if(evidence.accepted){result.developedProject=candidateRoot;result.outcome=AdaptiveExperimentOutcome::Complete;result.reason="counterfactual_hypothesis_verified";remember(cfg.experienceStore,"success",detail);result.experiencePersisted=!cfg.experienceStore.empty();throw std::runtime_error("finalize");}remember(cfg.experienceStore,"failed",detail);result.experiencePersisted=!cfg.experienceStore.empty();}if(number>=cfg.maxAttempts)break;}
        if(result.attempts.empty()) remember(cfg.experienceStore,"failed","no-observable-literal");
        result.experiencePersisted=!cfg.experienceStore.empty()&&std::filesystem::exists(cfg.experienceStore);
        result.outcome=AdaptiveExperimentOutcome::Blocked;
        result.reason="operator_grammar_exhausted_without_verified_hypothesis";
    } catch(const std::exception& error) {if(std::string(error.what())!="finalize"){result.outcome=AdaptiveExperimentOutcome::Failed;result.reason=error.what();}}
    result.originalUntouched=before==computeDirectoryTreeHash(original);writeReport(cfg,result);return result;
}
} // namespace genomic::gpi
